  "plans.backToWelcome": "Volver a la bienvenida",
  "plans.eyebrow": "Planes y funciones",
  "plans.title": "Comparar los planes de StockHaven",
  "plans.intro": "Una cuenta, cualquiera sea el plan que elija: Business cubre hasta cinco negocios. Los precios son mensuales en dólares estadounidenses, y los clientes nuevos elegibles del sitio web pueden recibir una prueba de siete días entre Essentials y Business. Actualizar una suscripción existente de Essentials a Business no reinicia la prueba ni crea otra prueba gratuita. Los precios de los planes del sitio web son antes de los impuestos aplicables, si los hubiera. Su cargo exacto se mostrará antes de que autorice una suscripción.",
  "plans.availableAtLaunch": "Disponible en el lanzamiento móvil",
