  "upgrade.pastDueTitle": "Pago vencido",
  "upgrade.pastDueBody": "Su último pago no se realizó, por lo que esta suscripción está vencida. Conserva el uso completo durante 14 días desde el pago fallido mientras lo corrige. Si no se corrige, la suscripción se cancela, el espacio de trabajo pasa a ser de solo lectura durante 15 días y luego la cuenta y toda su información se eliminan. Pagar en cualquier momento antes de la eliminación lo restablece todo. Actualice su método de pago a continuación. Si necesita ayuda, escriba a",
