  "billing.cancel.doneTitle": "Su suscripción está cancelada.",
  "billing.cancel.doneWithEnd": "Mantiene el acceso completo hasta el {endDate}. Después de esa fecha tiene un período de gracia de solo lectura de {graceDays} días: aún puede iniciar sesión y ver sus productos, pero no puede agregar, editar, eliminar, escanear, importar, exportar ni cambiar nada. {gracePart}",
  "billing.cancel.graceEndsOn": "Después de que el período de gracia de 15 días finalice el {date}, su cuenta y toda su información se eliminan permanentemente y no se pueden recuperar.",
  "billing.cancel.doneNoEnd": "Mantiene el acceso completo hasta el final de su período pagado. Después de eso, se aplica un período de gracia de solo lectura de 15 días. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "Canceló dentro de los 3 días de su primer cargo pagado, por lo que puede ser elegible para un reembolso de ese primer pago. Cancelar no emite el reembolso por sí mismo: solicítelo a través de {contact}.",
