  "billing.cancel.alreadyCanceledNoEnd": "Finaliza al final del período pagado actual. Mantiene el acceso completo hasta entonces.",
  "billing.cancel.appStoreNote": "Si alguna vez se suscribe a través de Google Play o la Apple App Store, es posible que deba cancelarla a través de la configuración de suscripciones de esa tienda. Este diálogo no puede detener la facturación de la tienda de aplicaciones. Desinstalar la aplicación o eliminar su cuenta de StockHaven no cancela una suscripción de la tienda.",
