  "auth.sameEmailNotice": "¿Ya tiene nuestra aplicación de Google Play o de la App Store? Use aquí el mismo correo, aquel con el que inicia sesión en la aplicación, para que su tienda y su inventario vengan con usted. Un correo distinto inicia una tienda totalmente nueva y vacía.",
