  "settings.security.title": "Seguridad y llaves de repuesto",
  "settings.security.description": "Configure sus llaves de repuesto ANTES de necesitarlas: si alguna vez pierde el acceso al correo de su cuenta, así es como recupera su tienda.",
  "settings.security.genericError": "Algo salió mal. Inténtelo de nuevo.",
