  "settings.security.backupCodesTitle": "Códigos de respaldo",
  "settings.security.backupCodesDesc": "Llaves de repuesto de un solo uso. Imprímalas o escríbalas y guárdelas en un lugar seguro: cada una puede devolverle el acceso una vez si pierde su correo.",
  "settings.security.codesRemaining": "Códigos de respaldo sin usar restantes: {count}",
