  "settings.security.codesOnceWarning": "Estos códigos se muestran solo una vez: guardamos solo una copia revuelta, así que ni siquiera nosotros podemos mostrarlos de nuevo. Generar un conjunto nuevo cancela cada código anterior.",
  "settings.security.printCodes": "Imprimir estos códigos",
