  "settings.security.backupEmailDesc": "Una segunda dirección de correo que usted controla. Si alguna vez su correo principal queda fuera de alcance, puede enviarse un código de recuperación aquí en su lugar.",
  "settings.security.backupEmailLabel": "Dirección de correo de respaldo",
