  "print.carrier.desc": "Compra el franqueo con el transportista, como haces hoy: esta app nunca vende franqueo, así que el precio que pagas es siempre el del transportista. Guarda aquí el archivo de la etiqueta y quedará en este pedido para siempre: tu registro, a la mano por si pasa algo.",
