  "print.style.title": "Estilo de documentos",
  "print.style.desc": "Haz tuyos tus documentos. Estas opciones visten tu factura, recibo, albarán, documentos de devolución, fichas de producto, hojas de conteo y listas de preparación, y se recuerdan para tu negocio.",
