  "staff.memberDialog.settingsAccessHint": "Las secciones marcadas aparecen en la Configuración de esta persona, donde puede verlas y cambiarlas. Las no marcadas quedan ocultas. La suscripción y la facturación nunca están aquí: son solo del dueño.",
  "staff.memberDialog.editNameHint": "Solo gerentes: esta marca no hace nada para el personal.",
  "login.staffWindowClosed": "La app se abre unos 10 minutos antes de tu turno programado, y todavía no es la hora de tu turno. Vuelve un poco antes de que empiece tu turno.",
  "login.staffWindowClosedNext": "La app se abre unos 10 minutos antes de tu turno programado. Tu próximo turno empieza {when}: vuelve un poco antes.",
  "apiErrors.code.staffOutsideWindow": "La app se abre unos 10 minutos antes de tu turno programado, y todavía no es la hora de tu turno.",
  "apiErrors.graceReadOnly": "Este espacio de trabajo es de solo lectura: la suscripción terminó y el periodo de gracia de 15 días permite ver productos solamente. Sin cambios, sin escaneos, sin importaciones ni exportaciones.",
  "apiErrors.subscriptionRequired": "Este espacio de trabajo no tiene una suscripción activa. Suscríbete a un plan para usarlo: el acceso empieza solo cuando se confirma la prueba o el pago.",
  "apiErrors.neutralStop": "Los cambios están desactivados por ahora. No se puede agregar ni cambiar nada en este momento: pregúntale al dueño del negocio si necesitas algo.",
