  "settings.policies.title": "Políticas y términos de tu tienda",
  "settings.policies.ownerDescription": "Tu tienda, tus reglas. Escribe aquí las políticas de tu tienda y tus términos y condiciones: escríbelos o sube un archivo. Cada nuevo miembro del equipo los ve una vez cuando empieza, y todo tu equipo puede leerlos aquí cuando quiera. Solo tú puedes cambiarlos.",
