  "settings.policyQuiz.expected": "Respuesta esperada",
  "settings.policyQuiz.expectedHint": "La respuesta que espera, en sus palabras. Una respuesta que coincide casi palabra por palabra cuenta como correcta en el momento; las demás le llegan para que las revise.",
  "settings.policyQuiz.hint": "Escriba preguntas sobre este documento para su equipo. Una persona las responde en Capacitación cuando usted marca esta capacitación para ella en su registro de Personal. No hay límite en la cantidad de preguntas que puede escribir.",
  "settings.policyQuiz.mcLabel": "Opción múltiple",
