  "settings.policyQuiz.passLineHint": "La puntuación —contando solo las respuestas de opción múltiple— que una persona necesita para terminar esta capacitación.",
  "settings.policyQuiz.question": "Pregunta",
  "settings.policyQuiz.remove": "Eliminar",
  "settings.policyQuiz.save": "Guardar preguntas",
  "settings.policyQuiz.saved": "Preguntas guardadas.",
  "settings.policyQuiz.title": "Preguntas para tu equipo",
  "staff.memberDialog.trainingAccessHint": "Leer las políticas de la tienda y los términos es para todos. Estas marcas asignan la capacitación con cuestionario que el dueño crea junto a cada documento en Ajustes.",
  "staffLib.area.trainingAccess": "Capacitación con cuestionario de políticas",
  "staffLib.perm.trainingPoliciesQuiz": "Capacitación con cuestionario de las Políticas de la tienda",
  "staffLib.perm.trainingTermsQuiz": "Capacitación con cuestionario de los Términos y condiciones",
  "training.comment.placeholder": "Lo que quiera decir sobre esta lección…",
  "training.comment.send": "Enviar comentario",
  "training.comment.sent": "Su comentario se envió al dueño.",
  "training.comment.title": "Deje un comentario para el dueño",
  "training.lessons.download-app.step1": "Luminous StockHaven puede vivir en su celular o su computadora como una aplicación de verdad, sin necesidad de una tienda de aplicaciones.",
  "training.lessons.download-app.step2": "Abra Ajustes y busque la tarjeta Descargar la aplicación. Está ahí para todos los roles, en ambos planes.",
  "training.lessons.download-app.step3": "Toque el botón de instalar y siga el aviso de su dispositivo. La aplicación llega a su pantalla de inicio con el nombre y el icono de la tienda.",
  "training.lessons.download-app.step4": "Ábrala desde su pantalla de inicio de ahí en adelante: inicia sesión de la misma manera y ve la misma tienda.",
  "training.lessons.download-app.title": "Descargue la aplicación en su dispositivo",
  "training.lessons.mgr-tax-rate.step1": "Los pedidos pueden llevar una tasa de impuesto sobre las ventas. El dueño define la tasa en Ajustes; es una sola tasa para toda la tienda.",
  "training.lessons.mgr-tax-rate.step2": "Cuando el dueño marca la sección de impuestos para usted en su registro de Personal, la tasa aparece también en sus Ajustes, y puede mantenerla actualizada ahí.",
  "training.lessons.mgr-tax-rate.step3": "La tasa es un porcentaje: 8.25 significa que el cliente paga 8.25% de impuesto además del precio de los productos del pedido.",
  "training.lessons.mgr-tax-rate.step4": "Cuando la tasa cambia, los pedidos nuevos usan la tasa nueva. Los pedidos ya hechos conservan la tasa con la que se hicieron.",
  "training.lessons.mgr-tax-rate.step5": "Si el dueño cambia el impuesto a Automático, un pedido nuevo completa su impuesto con la tasa base estatal del cliente en cuanto el estado está en el pedido, y lo vuelve a completar si el estado cambia. Son tasas base estatales; los impuestos locales pueden agregar más. Un pedido sin estado, o fuera de EE. UU., usa la tasa fija de la tienda, y un impuesto escrito en un pedido siempre manda.",
  "training.lessons.mgr-tax-rate.title": "La tasa de impuesto de la tienda",
  "training.lessons.owner-confidentiality.step5": "Aquí está el mapa completo. Su equipo ve su propio trabajo: su horario, sus tareas, sus recibos de pago, sus mensajes y las pantallas de la tienda que su rol abre. Nunca ve su periodo de prueba, en qué plan está el negocio, cuánto cuesta el plan, si un pago se realizó o que se alcanzó un límite del plan. Las pantallas de dinero —facturación, facturas y métodos de pago— son solo para el dueño, siempre.",
  "training.lessons.owner-confidentiality.step6": "Si la cuenta se detiene alguna vez, este es el mensaje exacto que ve su equipo: “Los cambios están desactivados por ahora. No se puede agregar ni cambiar nada en este momento: pregúntale al dueño del negocio si necesitas algo.” Nada en él menciona un plan, un precio o un pago.",
  "training.lessons.owner-confidentiality.step7": "Y cuando lo que detiene algo es un límite del plan, este es el mensaje exacto: “Eso no se puede agregar ahora — pregúntale al dueño del negocio, por favor.” Nunca dice que se alcanzó un límite: eso queda entre usted y la aplicación.",
  "training.lessons.staff-builds.step1": "Un paquete armado une productos en una sola cosa que se puede vender: un paquete, un kit o un set de regalo. Estos paquetes viven en la pantalla Paquetes y armados del menú.",
  "training.lessons.staff-builds.step2": "Abra un paquete armado para ver qué lleva: cada producto que lo forma y cuántos de cada uno usa.",
  "training.lessons.staff-builds.step3": "Cuando un paquete se arma o se vende, el inventario de sus partes se mueve con él: la aplicación mantiene las cuentas correctas por usted.",
  "training.lessons.staff-builds.step4": "Si falta una parte o una cuenta se ve mal, avísele a su gerente en vez de adivinar: los paquetes armados tocan muchos productos a la vez.",
  "training.lessons.staff-builds.title": "Paquetes y armados",
  "training.lessons.staff-cross-store.step1": "Cuando tu negocio tiene más de una tienda o sitio, las tiendas pueden pedirse inventario entre sí. Esas solicitudes llegan a la bandeja de entrada entre tiendas.",
  "training.lessons.staff-cross-store.step2": "Abra la bandeja desde el menú para ver qué está pidiendo otra tienda y qué le han enviado a su tienda.",
  "training.lessons.staff-cross-store.step3": "Responda una solicitud solo de la manera que su gerente le ha mostrado: enviar inventario fuera cambia las cuentas de su propia tienda.",
  "training.lessons.staff-cross-store.step4": "Si una solicitud se ve mal —el producto equivocado, o más de lo que tiene— no adivine. Avísele a su gerente.",
  "training.lessons.staff-cross-store.title": "La bandeja de entrada entre tiendas",
  "training.lessons.staff-reports.step1": "Los informes reúnen los números de la tienda —ventas, inventario y más— en un solo lugar. Los informes están en el menú.",
  "training.lessons.staff-reports.step2": "Abra un informe para ver sus números en las fechas que cubre. Las fechas son parte del informe: el mismo informe en otra semana cuenta una historia diferente.",
  "training.lessons.staff-reports.step3": "Algunos informes se pueden guardar fuera de la aplicación como archivos. Guárdelos fuera solo cuando su gerente o el dueño se lo pida.",
  "training.lessons.staff-reports.step4": "Los números de los informes salen del trabajo real de la tienda —pedidos, conteos y movimientos—, así que registrar todo con honestidad en las demás pantallas mantiene los informes verdaderos.",
  "training.lessons.staff-reports.title": "Cómo leer los informes",
  "training.lessons.welcome-basics.step6": "Cuando termine, cierre sesión: un enlace de Cerrar sesión está al final de cada página, justo encima de la línea de derechos de autor. Cerrar sesión lo saca de todas partes, en todos los dispositivos, para que nadie pueda entrar a su cuenta en una pantalla compartida.",
  "training.policy.belowLine": "Eso está por debajo de la línea: inténtelo otra vez.",
  "training.policy.markRead": "Ya lo leí: marcar como terminado",
