  "payroll.profile.note": "Estos datos se usan para sus formularios de pago e impuestos, y solo usted puede verlos aquí. Si algo debe cambiar, pídeselo al propietario o a su gerente: ellos son quienes pueden actualizarlos.",
  "payroll.profile.title": "Tus datos registrados",
