  "apiErrors.clockAdmin.ownerOnlyForManager": "Solo el dueño puede gestionar los llamados y los registros de horas de un gerente.",
  "apiErrors.clockFix.outBeforeIn": "La hora de salida debe ser posterior a la hora de entrada.",
  "apiErrors.clockFix.breakOutside": "Los horarios de descanso deben estar entre la hora de entrada y la hora de salida.",
  "apiErrors.clockFix.invalidTime": "Envía cada horario como una fecha y hora válidas.",
  "apiErrors.notFound.timeEntryFound": "Registro de horas no encontrado.",
  "training.lessons.mgr-clock-callin.title": "Llamados y correcciones de registro",
  "training.lessons.mgr-clock-callin.step1": "El dueño puede dar a un gerente una marca — Llamados y correcciones de registro. Con ella, puedes abrir una ventana de llamado para un miembro del personal y corregir registros de horas desde la página de Personal.",
  "training.lessons.mgr-clock-callin.step2": "Una ventana de llamado permite que una persona inicie sesión y registre su entrada cuando ningún turno la cubre. Ábrela desde la página de Personal, en la tarjeta de Llamados y salidas no registradas.",
  "training.lessons.mgr-clock-callin.step3": "La ventana permanece abierta hasta que esa persona registra su salida — luego sigue el periodo de gracia habitual de 10 minutos antes del cierre de sesión — o hasta que tú o el dueño la cierren antes. Nada la cierra por sí solo.",
  "training.lessons.mgr-clock-callin.step4": "Cuando alguien olvida registrar su salida, su registro se marca en la página de Personal y en Nómina una vez que termina el turno programado, y tú y el dueño reciben un aviso. El registro sigue contando hasta que se corrige.",
  "training.lessons.mgr-clock-callin.step5": "Corrige el registro desde la página de Personal: ajusta la entrada, la salida y cualquier horario de descanso. Un gerente corrige solo los registros del personal — los registros de un gerente los corrige el dueño.",
  "staffLib.perm.staffDocuments": "Documentos del personal",
  "staffLib.area.documentsAccess": "Documentos del personal",
  "staff.memberDialog.documentsAccessHint": "Solo para gerentes — con esta marca, este gerente puede abrir los archivos de documentos de los miembros del personal: el papeleo que se guarda de cada persona, como formularios W-4, solicitudes de empleo y copias de identificación. Primero se le pedirá confirmación — estos archivos contienen números de Seguro Social y fechas de nacimiento. Esta marca no hace nada para el personal.",
  "staff.documentsWarning.body": "Esta persona podrá ver información confidencial sobre los miembros de su personal, incluidos números de Seguro Social y fechas de nacimiento.",
  "staff.documentsWarning.confirm": "Sí, entiendo",
  "staff.documents.title": "Documentos del personal",
  "staff.documents.desc": "El papeleo que guarda de cada persona — formularios W-4, solicitudes de empleo, formularios de impuestos, copias de identificación. Solo usted, y un gerente al que le dé la marca de Documentos del personal, pueden abrir estos archivos.",
