  "nav.xstoreMessages": "Mensajes entre tiendas",
  "plansLib.businessIncludes.xstoreMessages": "Mensajes entre tiendas — todo tu equipo, en todos tus negocios",
  "xstore.title": "Mensajes entre tiendas",
  "xstore.help": "Todas las personas de esta cuenta, de todos tus negocios, en una sola bandeja de entrada. Escríbele aquí a cualquiera de ellas — por texto o por voz, con marcas de entrega y de lectura. Tus Mensajes dentro de la tienda quedan como están.",
  "xstore.empty": "Todavía no hay conversaciones. Inicia una con Mensaje nuevo.",
  "xstore.noPeople": "Todavía no hay nadie más a quien escribirle. Las personas aparecen aquí en cuanto se unen a uno de tus negocios e inician sesión.",
  "xstore.deliveredLabel": "Entregado",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "Los mensajes entre tiendas forman parte del plan Business.",
  "apiErrors.invalidValue.personNotPartAccount": "Esa persona no forma parte de esta cuenta.",
  "training.lessons.owner-xstore-messages.title": "Mensajes entre tus tiendas, para propietarios",
  "training.lessons.owner-xstore-messages.step1": "Mensajes entre tiendas es una segunda bandeja de entrada, separada de Mensajes. Mensajes es para la tienda en la que estás; esta puerta llega a todas las personas de tu cuenta, en cada negocio que tienes — hasta cinco.",
  "training.lessons.owner-xstore-messages.step2": "Abre Mensajes entre tiendas desde el menú e inicia una conversación con cualquier persona de la lista. La lista muestra a cada integrante del equipo de todos tus negocios que haya iniciado sesión, con las tiendas en las que trabaja.",
  "training.lessons.owner-xstore-messages.step3": "Las fotos acompañan: cada persona muestra su foto de perfil aprobada, o sus iniciales cuando no tiene ninguna. Cada mensaje lleva la fecha y la hora en que se envió.",
  "training.lessons.owner-xstore-messages.step4": "Debajo de tus propios mensajes puedes ver Entregado en cuanto un mensaje llega, y Leído en cuanto la otra persona abre la conversación. Las notas de voz también funcionan aquí, igual que en Mensajes.",
  "training.lessons.owner-xstore-messages.step5": "Las conversaciones aquí son privadas entre las dos personas que participan en ellas. Tu supervisión de los Mensajes dentro de la tienda no alcanza a las demás tiendas.",
  "training.lessons.mgr-xstore-messages.title": "Mensajes entre tus tiendas, para gerentes",
  "training.lessons.mgr-xstore-messages.step1": "Mensajes entre tiendas llega a todas las personas de esta cuenta, en todos los negocios — no solo a la tienda en la que estás. Está en el menú, separado de Mensajes.",
  "training.lessons.mgr-xstore-messages.step2": "Inicia una conversación desde la lista: ahí está cada integrante del equipo que haya iniciado sesión, con las tiendas en las que trabaja junto a su nombre.",
  "training.lessons.mgr-xstore-messages.step3": "Envía texto, o graba una nota de voz. Antes de que una nota de voz se envíe, puedes escucharla, descartarla o enviarla — igual que en Mensajes.",
  "training.lessons.mgr-xstore-messages.step4": "Tus mensajes muestran Entregado cuando llegan y Leído cuando la otra persona abre la conversación. La foto junto a cada nombre es la foto de perfil aprobada de esa persona.",
  "training.lessons.staff-xstore-messages.title": "Mensajes entre tus tiendas",
  "training.lessons.staff-xstore-messages.step1": "Mensajes entre tiendas es donde puedes llegar a cualquier persona de esta cuenta, en cualquiera de los negocios del propietario — una pregunta para otra tienda ya no tiene que esperar.",
  "training.lessons.staff-xstore-messages.step2": "Ábrelo desde el menú, elige a la persona y escribe. Si la persona que necesitas no aparece en la lista, todavía no ha iniciado sesión — aparecerá en cuanto lo haga.",
  "training.lessons.staff-xstore-messages.step3": "Aquí también puedes enviar notas de voz: graba, escucha y luego envíala o descártala. Cada mensaje muestra la fecha y la hora en que se envió.",
  "training.lessons.staff-xstore-messages.step4": "Cuando envías un mensaje, muestra Entregado en cuanto llega, y Leído en cuanto la otra persona abre la conversación. Una conversación es privada entre tú y la otra persona.",
