  "training.lessons.owner-ebay-connect.step5": "Una venta se vincula por el SKU, el UPC o el ISBN — cualquiera de los tres que traiga el listado. Si una venta no se puede vincular, espera bajo «Ventas que necesitan vincularse» en la página Conexiones de tiendas: vincúlala con su producto una vez, y esa venta — y las futuras como esa — se registran por sí mismas. «Revisar ventas ahora» trae todo lo reciente, y Desconectar detiene la conexión; las ventas ya registradas se quedan.",
